def _versionless(tid: str) -> str:
    """Strip version suffix from Ensembl IDs (e.g., ENST00000442987.3 -> ENST00000442987).
    
    Preserves PacBio IDs (PB.10.104) since the last number is the transcript ID, not a version.
    """
    # Don't strip PacBio IDs - the last number is the transcript ID, not a version
    if tid.startswith("PB."):
        return tid
    i = tid.rfind(".")
    return tid[:i] if i > 0 and tid[i+1:].isdigit() else tid


def _merge_intervals(intervals: List[Tuple[int, int]]):
    if not intervals:
        return []
    intervals = sorted(([min(a, b), max(a, b)] for a, b in intervals), key=lambda x: x[0])
    out = [intervals[0]]
    for s, e in intervals[1:]:
        ps, pe = out[-1]
        if s <= pe:
            out[-1][1] = max(pe, e)
        else:
            out.append([s, e])
    return out


def _parse_splicing_coordinates(coord_str: str) -> List[Tuple[int, int]]:
    """
    Parse splicing event coordinate string into list of (start, end) tuples.
    
    Coordinate format from classify_splicing_events:
      "chr:start:end:strand" or "chr:start:end:strand;chr:start:end:strand"
    
    Returns list of (start, end) genomic intervals.
    """
    if not coord_str or coord_str == "NA":
        return []
    
    intervals = []
    for part in coord_str.split(";"):
        parts = part.strip().split(":")
        if len(parts) >= 3:
            try:
                # Format: chrom:start:end:strand or start:end
                # Try to extract start and end
                if len(parts) == 4:
                    # chrom:start:end:strand
                    start, end = int(parts[1]), int(parts[2])
                elif len(parts) == 3:
                    # chrom:start:end or start:end:strand
                    try:
                        start, end = int(parts[0]), int(parts[1])
                    except ValueError:
                        start, end = int(parts[1]), int(parts[2])
                else:
                    start, end = int(parts[0]), int(parts[1])
                intervals.append((min(start, end), max(start, end)))
            except (ValueError, IndexError):
                continue
    return intervals


def _get_events_vs_reference(
    transcript_data,
    tid: str,
    reference_tid: str,
) -> Tuple[List[Tuple[int, int]], List[str]]:
    """
    Get splicing event regions comparing a transcript to a reference.
    
    Returns (intervals, event_types) tuple.
    """
    tid_clean = _versionless(tid)
    ref_clean = _versionless(reference_tid)
    
    if tid_clean == ref_clean:
        return [], []
    
    try:
        events_df = transcript_data.classify_splicing_events(ref_clean, tid_clean)
    except Exception:
        return [], []
    
    if events_df is None or events_df.empty:
        return [], []
    
    intervals = []
    event_types = []
    
    for _, row in events_df.iterrows():
        event_type = str(row.get('event', ''))
        coords = str(row.get('coordinates', ''))
        
        parsed = _parse_splicing_coordinates(coords)
        intervals.extend(parsed)
        if event_type and event_type not in event_types:
            event_types.append(event_type)
    
    return intervals, event_types


