class TranscriptPlots:
    """
    Visualize transcript structures (intron-compressed, optional exon scaling)
    and provide a right-hand panel (heatmap or dotplot).
    """

    # right-panel geometry defaults (chosen to match EDF1 TRAC/NAS layout)
    panel_x0: float = 1.08
    panel_pad: float = 0.02
    panel_width: float = 0.32
    colorbar_width: float = 0.035

    # row geometry
    row_pitch: float = 0.60
    exon_height: float = 0.18
    top_margin: float = 0.30
    bottom_margin: float = 0.20

    def __init__(
        self,
        *,
        transcript_data,
        intron_scale: float = 0.12,
        intron_scale_mode: str = "relative",  # 'relative' | 'fixed'
        intron_fixed_length: float = 5.0,
        exon_scale_mode: str = "none",        # 'none' | 'relative' | 'fixed'
        exon_scale: float = 1.0,
        exon_fixed_length: float = 8.0,
        exon_min_length: float = 1.5,
        intron_min_length: float = 1.0,
        label_drop: float = 0.10,
        show_length: bool = False,
        length_mode: str = "exonic",          # 'exonic' | 'span'
        # NEW visual style parameters
        palette: str = "wong",                # 'wong' | 'tol' | 'tab10' | list
        exon_edge_style: str = "soft",        # 'soft' | 'rounded' | 'sharp'
        intron_style: str = "line",           # 'line' | 'chevron'
        color_offset: int = 0,               # rotate palette by this many steps
    ):
        # Palette selection
        if isinstance(palette, list):
            self.colors = list(palette)
        elif palette == "wong":
            self.colors = list(_PALETTE_WONG)
        elif palette == "tol":
            self.colors = list(_PALETTE_TOL_MUTED)
        elif palette == "tab10":
            self.colors = list(_DEFAULT_COLORS)
        else:
            self.colors = list(_PALETTE_WONG)  # default to wong
        if color_offset and len(self.colors) > 1:
            n = color_offset % len(self.colors)
            self.colors = self.colors[n:] + self.colors[:n]
        
        # Visual style
        self.exon_edge_style = exon_edge_style
        self.intron_style = intron_style

        # introns
        self.intron_scale = float(intron_scale)
        self.intron_scale_mode = intron_scale_mode
        self.intron_fixed_length = float(intron_fixed_length)

        # exons
        self.exon_scale_mode = exon_scale_mode
        self.exon_scale = float(exon_scale)
        self.exon_fixed_length = float(exon_fixed_length)

        # min widths (scaled units)
        self.exon_min_length = float(exon_min_length)
        self.intron_min_length = float(intron_min_length)

        # labels / bars
        self.label_drop = float(label_drop)
        self.show_length = bool(show_length)
        self.length_mode = length_mode

        self.transcript_data = transcript_data

    # ------------------ data access ------------------
    
    def _panel_width_for(self, n_cols: int) -> float:
        """
        Choose panel width as a function of the number of columns,
        matching the EDF1 TRAC/NAS layout so x-tick labels have
        sane horizontal space.
        """
        min_col_w, max_panel_w = 0.070, 0.92
        # 0.026 is a small per-column padding like in the EDF1 code
        need_w = n_cols * (min_col_w + 0.026) - (0.026 if n_cols > 0 else 0)
        return min(max_panel_w, max(0.22, need_w))

    def _get_exons_and_strand(self, tid: str):
        return self.transcript_data.get_exon_coords_and_strand(_versionless(tid))

    def _get_cds_bounds(self, tid: str):
        info = self.transcript_data.get_transcript_info(_versionless(tid))
        cs, ce = info.get("cds_start"), info.get("cds_end")
        if cs is None or ce is None:
            return None
        try:
            return int(cs), int(ce)
        except Exception:
            return None

    # ---------------- mapping helpers ----------------

    def _make_global_mapping(self, exons_lists):
        """
        Piecewise-linear mapper f: genomic -> [0,1] with intron compression (relative/fixed)
        and optional exon scaling (none/relative/fixed).
        """
        intervals = []
        for exs in exons_lists:
            for a, b in exs:
                s, e = (min(a, b), max(a, b))
                intervals.append([s, e])
        U = np.asarray(_merge_intervals(intervals), dtype=np.int64)
        if U.size == 0:
            raise ValueError("No exonic intervals!")

        g0, g1 = int(U[0, 0]), int(U[-1, 1])
        exon_starts = U[:, 0].astype(np.int64)
        exon_ends = U[:, 1].astype(np.int64)
        exon_L = (exon_ends - exon_starts).astype(float)

        gap_starts = exon_ends[:-1]
        gap_ends = exon_starts[1:]
        gap_L = (gap_ends - gap_starts).astype(float)

        # exons
        if self.exon_scale_mode == "relative":
            exon_scaled = np.maximum(exon_L * self.exon_scale, self.exon_min_length)
        elif self.exon_scale_mode == "fixed":
            exon_scaled = np.maximum(
                np.full_like(exon_L, self.exon_fixed_length, dtype=float),
                self.exon_min_length,
            )
        else:  # none
            exon_scaled = np.maximum(exon_L, self.exon_min_length)
        exon_slope = exon_scaled / np.maximum(exon_L, 1e-9)

        # introns
        if gap_L.size:
            if self.intron_scale_mode == "relative":
                gap_scaled = np.maximum(gap_L * self.intron_scale, self.intron_min_length)
            else:  # fixed
                gap_scaled = np.maximum(
                    np.full_like(gap_L, self.intron_fixed_length, dtype=float),
                    self.intron_min_length,
                )
            gap_slope = gap_scaled / np.maximum(gap_L, 1e-9)
        else:
            gap_slope = np.array([], float)
            gap_starts = gap_ends = np.array([], np.int64)

        seg_starts = []
        seg_ends = []
        seg_slope = []
        for i in range(len(exon_L)):
            seg_starts.append(exon_starts[i])
            seg_ends.append(exon_ends[i])
            seg_slope.append(exon_slope[i])
            if i < len(gap_L):
                seg_starts.append(gap_starts[i])
                seg_ends.append(gap_ends[i])
                seg_slope.append(gap_slope[i])

        seg_starts = np.asarray(seg_starts, np.int64)
        seg_ends = np.asarray(seg_ends, np.int64)
        seg_slope = np.asarray(seg_slope, float)
        seg_len = (seg_ends - seg_starts).astype(float)
        seg_scaled = seg_len * seg_slope
        prefix_scaled = np.concatenate(([0.0], np.cumsum(seg_scaled)))
        total_scaled = prefix_scaled[-1] or 1.0
        ends_for_search = seg_ends

        def raw(x_arr):
            x_arr = np.asarray(x_arr, float)
            idx = np.searchsorted(ends_for_search, x_arr, side="right")
            idx = np.minimum(idx, len(seg_ends) - 1)
            start = seg_starts[idx].astype(float)
            end = seg_ends[idx].astype(float)
            slope = seg_slope[idx]
            x_clamped = np.minimum(np.maximum(x_arr, start), end)
            scaled = prefix_scaled[idx] + slope * (x_clamped - start)
            return scaled

        def f(x):
            return float(raw(np.array([x]))[0] / total_scaled)

        return f, (g0, g1)

    # ---------------- rows & axes ----------------

    def _row_centers(self, n_rows: int) -> List[float]:
        return [-(i * self.row_pitch) for i in range(n_rows)]

    def _prep_axes(
        self,
        n_rows: int,
        *,
        reserve_panel_space: bool,
        fig_width: float | None = None,
        extra_top: float = 0.0,
        extra_left: float = 0.0,
        fig_height: float | None = None,
    ):
        plt.close("all")
        W = float(fig_width) if fig_width else 20.0
        H = float(fig_height) if fig_height else max(2.5, 2.1 * n_rows)
        fig, ax = plt.subplots(figsize=(W, H))

        if reserve_panel_space:
            right = (
                self.panel_x0
                + self.panel_width
                + self.panel_pad
                + self.colorbar_width
                + 0.06
            )
        else:
            right = 1.05

        ax.set_xlim(-0.05 - extra_left, right)
        ycs = self._row_centers(n_rows)
        y_top = self.top_margin + float(extra_top)
        y_bottom = (
            (ycs[-1] - self.row_pitch / 2) - self.bottom_margin if n_rows > 0 else -0.2
        )
        ax.set_ylim(y_bottom, y_top)
        ax.margins(0.0)
        ax.axis("off")
        return fig, ax, ycs

    # ---------------- helper methods for drawing ----------------
    
    def _draw_exon_rect(
        self,
        ax,
        x: float,
        y: float,
        width: float,
        height: float,
        *,
        facecolor: str,
        edge_style: str = "soft",
        zorder: int = 1,
        edgecolor: str = None,
        linewidth: float = None,
    ):
        """Draw an exon rectangle with configurable edge styling.
        
        Parameters
        ----------
        edge_style : str
            "soft" - Slight rounding on corners
            "rounded" - Pill-shaped with FancyBboxPatch
            "sharp" - Traditional rectangular
        """
        edge_color = edgecolor or _EDGE_COLOR
        edge_width = linewidth if linewidth is not None else 0.8
        
        if edge_style == "rounded":
            rounding = min(width * 0.15, height * 0.4, 0.015)
            patch = FancyBboxPatch(
                (x, y), width, height,
                boxstyle=f"round,pad=0,rounding_size={rounding}",
                facecolor=facecolor,
                edgecolor=edge_color,
                linewidth=edge_width,
                zorder=zorder,
            )
        elif edge_style == "soft":
            rounding = min(width * 0.08, height * 0.20, 0.010)
            patch = FancyBboxPatch(
                (x, y), width, height,
                boxstyle=f"round,pad=0,rounding_size={rounding}",
                facecolor=facecolor,
                edgecolor=edge_color,
                linewidth=edge_width,
                zorder=zorder,
            )
        else:  # sharp
            patch = Rectangle(
                (x, y), width, height,
                fc=facecolor, ec=edge_color,
                lw=edge_width, zorder=zorder,
            )
        
        ax.add_patch(patch)
        return patch
    
    def _draw_intron(
        self,
        ax,
        x_start: float,
        x_end: float,
        y_center: float,
        strand: int,
        *,
        style: str = "line",
        color: str = None,
        linewidth: float = 1.2,
    ):
        """Draw intron connector between exons.
        
        Parameters
        ----------
        style : str
            "line" - Simple horizontal line
            "chevron" - Hat/peak shape pointing in strand direction (IGV style)
        """
        color = color or _INTRON_COLOR
        
        if style == "line":
            ax.plot(
                [x_start, x_end], [y_center, y_center],
                color=color, lw=linewidth, zorder=0,
                solid_capstyle='round',
            )
            return
        
        # Chevron style
        mid_x = (x_start + x_end) / 2
        intron_width = abs(x_end - x_start)
        
        # Peak height proportional to intron width but capped
        peak_height = min(_INTRON_CHEVRON_HEIGHT, intron_width * 0.25)
        peak_y = y_center + (peak_height if strand >= 0 else -peak_height)
        
        ax.plot(
            [x_start, mid_x, x_end],
            [y_center, peak_y, y_center],
            color=color, lw=linewidth, zorder=0,
            solid_capstyle='round',
            solid_joinstyle='round',
        )

    def _draw_highlight_box(
        self,
        ax,
        x_start: float,
        x_end: float,
        y_center: float,
        height: float,
        *,
        color: str = None,
        alpha: float = None,
        linewidth: float = None,
        linestyle: str = "-",
        padding: float = 0.02,
    ):
        """Draw a bounding box to highlight a genomic region.
        
        Parameters
        ----------
        ax : matplotlib Axes
        x_start, x_end : float
            Mapped x-coordinates (0-1 scale)
        y_center : float
            Center y-coordinate for the row
        height : float
            Height of the highlight box
        color : str, optional
            Box edge/fill color (default: _EVENT_HIGHLIGHT_COLOR)
        alpha : float, optional
            Fill alpha (default: _EVENT_BOX_ALPHA)
        linewidth : float, optional
            Edge linewidth (default: _EVENT_BOX_LINEWIDTH)
        linestyle : str
            Line style for edge (default: "-")
        padding : float
            Extra padding around the region
        """
        color = color or _EVENT_HIGHLIGHT_COLOR
        alpha = alpha if alpha is not None else _EVENT_BOX_ALPHA
        linewidth = linewidth if linewidth is not None else _EVENT_BOX_LINEWIDTH
        
        x0 = min(x_start, x_end) - padding
        x1 = max(x_start, x_end) + padding
        y0 = y_center - height / 2 - padding
        
        box = FancyBboxPatch(
            (x0, y0), x1 - x0, height + 2 * padding,
            boxstyle="round,pad=0,rounding_size=0.01",
            facecolor=color,
            edgecolor=color,
            alpha=alpha,
            linewidth=linewidth,
            linestyle=linestyle,
            zorder=0.5,
        )
        ax.add_patch(box)
        
        # Also draw a more visible edge
        edge_box = FancyBboxPatch(
            (x0, y0), x1 - x0, height + 2 * padding,
            boxstyle="round,pad=0,rounding_size=0.01",
            facecolor='none',
            edgecolor=color,
            linewidth=linewidth,
            linestyle=linestyle,
            zorder=2.5,
        )
        ax.add_patch(edge_box)
        
        return box

    # ---------------- rich row renderer ----------------

    def _draw_one(
            self,
            exons_e_s,
            strand,
            color,
            tid_label,
            mapper,
            *,
            y_center,
            cds_bounds,
            show_row_bounds: bool = False,
            length_bar: dict | None = None,
            genome_bounds: tuple[int, int] | None = None,
            highlight_intervals: List[Tuple[int, int]] | None = None,
            highlight_color: str | None = None,
            highlight_style: str = "box",
            event_label: str | None = None,
            event_label_fontsize: int = 10,
            spliced_length: int | None = None,
        ):
            ax = plt.gca()
            h = self.exon_height
            y0 = y_center - h / 2.0
            grey = _UI_GREY

            # exons in genomic order (independent of strand for drawing introns)
            ex = [[min(a, b), max(a, b)] for a, b in exons_e_s]
            ex.sort(key=lambda e: e[0], reverse=(strand < 0))

            # ---- Draw highlight boxes FIRST (behind exons) ----
            if highlight_intervals and highlight_style == "box":
                for (hs, he) in highlight_intervals:
                    xs_h = mapper(int(hs))
                    xe_h = mapper(int(he))
                    self._draw_highlight_box(
                        ax, xs_h, xe_h, y_center, h,
                        color=highlight_color,
                    )

            # introns - use new helper method
            for i in range(len(ex) - 1):
                self._draw_intron(
                    ax,
                    mapper(ex[i][1]),
                    mapper(ex[i + 1][0]),
                    y_center,
                    strand,
                    style=self.intron_style,
                    color=_INTRON_COLOR,
                )

            # Determine which exons overlap with highlight regions
            highlighted_exons = set()
            if highlight_intervals and highlight_style == "color":
                for idx, (s, e) in enumerate(ex):
                    for (hs, he) in highlight_intervals:
                        # Check for overlap
                        if not (e < hs or s > he):
                            highlighted_exons.add(idx)

            # exons + CDS/UTR if available - use new helper method
            if cds_bounds is None:
                for idx, (s, e) in enumerate(ex):
                    xs, xe = mapper(int(s)), mapper(int(e))
                    # Use highlight color if this exon is involved in the event
                    fc = highlight_color if (idx in highlighted_exons and highlight_color) else color
                    ec = highlight_color if (idx in highlighted_exons and highlight_color) else None
                    lw = 2.0 if idx in highlighted_exons else None
                    self._draw_exon_rect(
                        ax, xs, y0, xe - xs, h,
                        facecolor=fc,
                        edge_style=self.exon_edge_style,
                        zorder=1,
                        edgecolor=ec,
                        linewidth=lw,
                    )
            else:
                cs, ce = sorted(cds_bounds)
                utr_h = h * 0.60
                utr_y = y_center - utr_h / 2.0
                for idx, (s, e) in enumerate(ex):
                    s, e = int(s), int(e)
                    is_highlighted = idx in highlighted_exons
                    fc_highlight = highlight_color if (is_highlighted and highlight_color) else None
                    ec_highlight = highlight_color if (is_highlighted and highlight_color) else None
                    lw_highlight = 2.0 if is_highlighted else None
                    
                    if s < cs:  # 5' UTR
                        xs, xe = mapper(s), mapper(min(e, cs))
                        if xe > xs:
                            fc = fc_highlight or color
                            self._draw_exon_rect(
                                ax, xs, utr_y, xe - xs, utr_h,
                                facecolor=fc,
                                edge_style=self.exon_edge_style,
                                zorder=1,
                                edgecolor=ec_highlight,
                                linewidth=lw_highlight,
                            )
                    c0, c1 = max(s, cs), min(e, ce)  # CDS
                    if c0 < c1:
                        xs, xe = mapper(c0), mapper(c1)
                        fc = fc_highlight or color
                        self._draw_exon_rect(
                            ax, xs, y0, xe - xs, h,
                            facecolor=fc,
                            edge_style=self.exon_edge_style,
                            zorder=1,
                            edgecolor=ec_highlight,
                            linewidth=lw_highlight,
                        )
                    if e > ce:  # 3' UTR
                        xs, xe = mapper(max(s, ce)), mapper(e)
                        if xe > xs:
                            fc = fc_highlight or color
                            self._draw_exon_rect(
                                ax, xs, utr_y, xe - xs, utr_h,
                                facecolor=fc,
                                edge_style=self.exon_edge_style,
                                zorder=1,
                                edgecolor=ec_highlight,
                                linewidth=lw_highlight,
                            )

            # label (right side) - improved typography
            label_y = y_center - h * (1 + self.label_drop)
            ax.text(
                0.995,
                label_y,
                tid_label,
                ha="right",
                va="top",
                fontsize=11,
                fontweight='bold',
                color='#1a1a1a',
            )

            # spliced length (left, muted)
            if spliced_length is not None:
                kb = spliced_length / 1e3
                length_str = f"{kb:.2f} kb" if kb < 10 else f"{kb:.1f} kb"
                ax.text(0.005, label_y, length_str, ha="left", va="top",
                        fontsize=10, fontstyle="italic", color=_UI_LIGHT_GREY)

            # Event label (far left, in line with transcript ID)
            if event_label:
                ax.text(
                    0.005,
                    label_y,
                    event_label,
                    ha="left",
                    va="top",
                    fontsize=event_label_fontsize,
                    fontweight="bold",
                    fontstyle="italic",
                    color=highlight_color or _EVENT_HIGHLIGHT_COLOR,
                )

            # ---------------- strand arrow: full displayed gene span ----------------
            arrow_y = y0 - 0.25 * h

            # use global displayed gene bounds if provided, otherwise per-transcript span
            if genome_bounds is not None:
                g_start, g_end = genome_bounds
                xs = mapper(int(g_start))
                xe = mapper(int(g_end))
            elif ex:
                smin = min(s for s, _ in ex)
                smax = max(e for _, e in ex)
                xs, xe = mapper(int(smin)), mapper(int(smax))
            else:
                xs, xe = 0.0, 1.0

            if strand >= 0:
                ax.arrow(
                    xs,
                    arrow_y,
                    xe - xs,
                    0.0,
                    width=0.002,
                    head_length=0.012,
                    head_width=0.06,
                    length_includes_head=True,
                    overhang=0.3,
                    color=_UI_LIGHT_GREY,
                    zorder=0,
                )
            else:
                ax.arrow(
                    xe,
                    arrow_y,
                    xs - xe,
                    0.0,
                    width=0.002,
                    head_length=0.012,
                    head_width=0.06,
                    length_includes_head=True,
                    overhang=0.3,
                    color=_UI_LIGHT_GREY,
                    zorder=0,
                )

            # ---------------- optional row-bounds ticks (as before) ----------------
            if show_row_bounds and ex:
                smin = min(s for s, _ in ex)
                smax = max(e for _, e in ex)
                xs_rb, xe_rb = mapper(int(smin)), mapper(int(smax))
                ax.plot([xs_rb, xs_rb], [arrow_y - 0.03, arrow_y + 0.03], color=grey, lw=0.9)
                ax.plot([xe_rb, xe_rb], [arrow_y - 0.03, arrow_y + 0.03], color=grey, lw=0.9)

            # ---------------- per-row length bar (left, unchanged) -----------------
            if length_bar is not None:
                bx0 = float(length_bar.get("x0", 0.02))
                bx1 = float(length_bar.get("x1", 0.20))
                frac = float(length_bar.get("frac", 0.0))
                label = str(length_bar.get("label", ""))
                frac = max(0.0, min(1.0, frac))
                bw = (bx1 - bx0) * frac
                bh = 0.030
                by = arrow_y - bh
                ax.add_patch(
                    Rectangle(
                        (bx0, by),
                        bw,
                        bh,
                        fc=grey,
                        ec="none",
                        alpha=0.65,
                        zorder=0,
                    )
                )
                if label:
                    ax.text(
                        bx0 + bw + 0.006,
                        by - 0.010,
                        label,
                        ha="left",
                        va="top",
                        fontsize=11,
                        color=grey,
                    )


    def _draw_top_ruler(self, ax, mapper, g0: int, g1: int, yref: float,
                            contig: Optional[str], gene_label: str):
            """Draw top ruler with improved text hierarchy."""
            x0, x1 = mapper(int(g0)), mapper(int(g1))
            
            # Smoother ruler line with rounded caps
            ax.plot(
                [x0, x1], [yref, yref],
                color=_UI_LIGHT_GREY, lw=1.2,
                solid_capstyle='round', zorder=1,
            )
            
            # End ticks
            ax.vlines(x0, yref - 0.02, yref + 0.02, lw=0.9, color=_UI_LIGHT_GREY)
            ax.vlines(x1, yref - 0.02, yref + 0.02, lw=0.9, color=_UI_LIGHT_GREY)

            # Genomic coordinates at ends - smaller, lighter
            ax.text(
                x0,
                yref + 0.02,
                f"{int(g0):,}",
                ha="center",
                va="bottom",
                fontsize=8,
                color=_UI_LIGHT_GREY,
            )
            ax.text(
                x1,
                yref + 0.02,
                f"{int(g1):,}",
                ha="center",
                va="bottom",
                fontsize=8,
                color=_UI_LIGHT_GREY,
            )

            # Locus string (chr:start-end) - secondary prominence
            span_kb = (int(g1) - int(g0) + 1) / 1e3
            locus = (
                f"{contig}: {int(g0):,}-{int(g1):,} ({span_kb:.1f} kb)"
                if contig
                else f"{int(g0):,}-{int(g1):,} ({span_kb:.1f} kb)"
            )
            ax.text(
                (x0 + x1) / 2,
                yref + 0.08,
                locus,
                ha="center",
                va="bottom",
                fontsize=9,
                color=_UI_GREY,
            )

            # Gene label - most prominent, italic for gene symbols
            if gene_label:
                ax.text(
                    (x0 + x1) / 2,
                    yref + 0.18,
                    gene_label,
                    ha="center",
                    va="bottom",
                    fontsize=14,
                    fontweight="bold",
                    fontstyle="italic",
                    color="#1a1a1a",
                )



    # ---------------- layout used by public methods ----------------

    def _layout_and_mapper(self, transcripts_ids, *, draw_cds=False):
        tids = [_versionless(t) for t in transcripts_ids]
        exons_list, strands, cds_map, exonic_len, genomic_span = [], [], {}, [], []
        for tid in tids:
            exs, st = self._get_exons_and_strand(tid)
            exons_list.append(exs)
            strands.append(st)
            cds_map[tid] = self._get_cds_bounds(tid) if draw_cds else None
            exonic_len.append(sum(abs(b - a) for a, b in exs))
            starts = [min(a, b) for a, b in exs]
            ends = [max(a, b) for a, b in exs]
            genomic_span.append(max(ends) - min(starts))
        f, (g0, g1) = self._make_global_mapping(exons_list)

        uniq = set()
        for tid, exs in zip(tids, exons_list):
            for a, b in exs:
                s, e = (min(a, b), max(a, b))
                uniq.add(s)
                uniq.add(e)
            if cds_map[tid] is not None:
                cs, ce = cds_map[tid]
                uniq.add(int(cs))
                uniq.add(int(ce))
        cache = {g: f(g) for g in sorted(uniq)}
        mapper = lambda x: cache.setdefault(x, f(x))
        return (
            tids,
            exons_list,
            strands,
            cds_map,
            mapper,
            (g0, g1),
            np.array(exonic_len),
            np.array(genomic_span),
        )

    def _contig_from_transcripts(self, tids: List[str]) -> Optional[str]:
        info = self.transcript_data.get_transcript_info(_versionless(tids[0]))
        for k in ("contig", "chrom", "seqname", "chromosome", "chr"):
            if k in info and info[k]:
                c = str(info[k])
                return c if c.startswith("chr") else f"chr{c}"
        return None

    def _gene_label_from_transcripts(self, tids: List[str]) -> str:
        td = self.transcript_data
        symbols, gene_ids = [], []
        for t in tids:
            info = td.get_transcript_info(_versionless(t))
            for k in ("gene_name", "gene", "symbol", "gene_symbol", "Name"):
                if k in info and info[k]:
                    symbols.append(str(info[k]))
                    break
            if "gene_id" in info and info["gene_id"]:
                gene_ids.append(str(info["gene_id"]))
        if symbols:
            s, n = np.unique(symbols, return_counts=True)
            return s[np.argmax(n)]
        if gene_ids:
            return gene_ids[0]
        return _versionless(tids[0]) if tids else ""

    # --------------------- right panel helpers ---------------------
    
    def _panel_axes(self, host_ax, n_rows, n_cols, *, x0, y_top, y_bottom):
            # use dynamic width based on number of columns
        panel_w = self._panel_width_for(n_cols)
        axP = inset_axes(
            host_ax,
            width="100%",
            height="100%",
            loc="lower left",
            bbox_to_anchor=(x0, y_bottom, panel_w, y_top - y_bottom),
            bbox_transform=host_ax.transData,
            borderpad=0,
        )
        axP.set_xlim(-0.5, n_cols - 0.5)
        axP.set_ylim(-0.5, n_rows - 0.5)
        axP.invert_yaxis()
        for s in axP.spines.values():
            s.set_visible(False)
        axP.tick_params(axis="both", length=0)
        return axP
    
    

    def _draw_ct_color_band(self, ax_ref, n_cols, band_colors):
        if not band_colors:
            return
        trans = ax_ref.get_xaxis_transform()
        y = 1.02
        for j, c in enumerate(band_colors):
            if c is None:
                continue
            ax_ref.add_patch(
                Rectangle(
                    (j - 0.5, y),
                    1.0,
                    0.06,
                    transform=trans,
                    clip_on=False,
                    facecolor=c,
                    edgecolor="black",
                    linewidth=0.4,
                    zorder=3,
                )
            )
    #
    def _draw_heatmap_panel(
        self,
        fig,
        axP,
        values,
        *,
        vmin,
        vmax,
        cmap_name,
        show_grid,
        cbar_label,
        cax=None,
        make_colorbar: bool = True,
    ):
        M = np.asarray(values, float)
        if M.ndim != 2:
            raise ValueError("values must be a 2D matrix.")
        n_rows, n_cols = M.shape

        try:
            cmap = mpl.colormaps[cmap_name]
        except Exception:
            cmap = mpl.cm.get_cmap(cmap_name)

        im = axP.imshow(
            M,
            aspect="auto",
            interpolation="nearest",
            origin="lower",
            cmap=cmap,
            vmin=vmin,
            vmax=vmax,
            extent=(-0.5, n_cols - 0.5, -0.5, n_rows - 0.5),
        )

        for s in axP.spines.values():
            s.set_visible(False)
        axP.tick_params(axis="both", length=0)

        if show_grid:
            axP.set_xticks(np.arange(-0.5, n_cols, 1), minor=True)
            axP.set_yticks(np.arange(-0.5, n_rows, 1), minor=True)
            axP.grid(which="minor", color="#e6e6e6", linewidth=0.6)

        cb = None
        if make_colorbar and cax is not None:
            cb = fig.colorbar(im, cax=cax)
            cb.set_label(cbar_label, rotation=270, va="center", labelpad=10, fontsize=10)
            cb.ax.tick_params(labelsize=9)

        return im, cb

    #
    def _draw_dot_panel(
        self,
        fig,
        axP,
        dot_color,
        dot_size,
        *,
        vmin,
        vmax,
        cmap_name,
        cbar_label,
        cax=None,
        make_colorbar: bool = True,
    ):
        R, C = dot_color.shape
        X, Y = np.meshgrid(np.arange(C), np.arange(R))
        s = np.array(dot_size, float)
        if np.nanmax(s) > 1.0:
            s = (s - np.nanmin(s)) / (np.nanmax(s) - np.nanmin(s) + 1e-9)
        S = 16.0 + s * (180.0 - 16.0)

        sc = axP.scatter(
            X.ravel(),
            Y.ravel(),
            c=dot_color.ravel(),
            cmap=mpl.cm.get_cmap(cmap_name),
            vmin=vmin,
            vmax=vmax,
            s=np.nan_to_num(S, nan=16.0).ravel(),
            edgecolors="#333333",
            linewidths=0.3,
            zorder=2,
        )

        cb = None
        if make_colorbar and cax is not None:
            cb = fig.colorbar(sc, cax=cax)
            cb.set_label(cbar_label, rotation=270, va="center", labelpad=10, fontsize=10)
            cb.ax.tick_params(labelsize=9)

        return sc, cb


    # ----------------------- public methods -----------------------

    def draw_transcripts_list(
            self,
            transcripts_ids: List[str],
            colors: Optional[List[str]] = None,
            *,
            draw_cds: bool = False,
            show_ticks: bool = True,
            show_row_bounds: bool = False,
            title_gene: Optional[str] = None,
            fig_width: float | None = None,
            # Splicing event visualization options
            reference_tx: Optional[str] = None,
            highlight_style: Optional[str] = None,
            highlight_color: Optional[str] = None,
            show_event_labels: bool = False,
            event_label_fontsize: int = 10,
            show_end_labels: bool = True,
            show_spliced_length: bool = True,
        ):
            """
            Draw a list of transcripts with optional splicing event highlighting.
            
            Parameters
            ----------
            transcripts_ids : List[str]
                List of transcript IDs to draw
            colors : Optional[List[str]]
                Custom colors for each transcript
            draw_cds : bool
                Whether to draw CDS/UTR distinction
            show_ticks : bool
                Whether to show top ruler with coordinates
            show_row_bounds : bool
                Whether to show row boundary markers
            title_gene : Optional[str]
                Custom gene label for the title
            fig_width : float, optional
                Figure width
            reference_tx : Optional[str]
                Reference transcript ID for splicing comparison.
                If None, first transcript is used as reference.
                Events are computed comparing each transcript to the reference.
            highlight_style : Optional[str]
                How to highlight splicing events:
                - "box": Draw bounding boxes around affected regions
                - "color": Color affected exons differently
                - None: No highlighting
            highlight_color : Optional[str]
                Color for highlighting (default: red-ish color)
            show_event_labels : bool
                Whether to show event type labels (MXE, SE, etc.) below transcript ID.
                Only shown for non-reference transcripts.
            event_label_fontsize : int
                Font size for event labels
            
            Returns
            -------
            matplotlib.figure.Figure
            """
            (
                tids,
                exons_list,
                strands,
                cds_map,
                mapper,
                (g0, g1),
                exonic_len,
                genomic_span,
            ) = self._layout_and_mapper(transcripts_ids, draw_cds=draw_cds)

            # Determine reference transcript
            if reference_tx is not None:
                ref_tid = _versionless(reference_tx)
            else:
                ref_tid = tids[0] if tids else None

            extra_top = 0.22 if show_ticks else 0.0

            fig, ax, ycs = self._prep_axes(
                len(tids),
                reserve_panel_space=False,
                fig_width=fig_width,
                extra_top=extra_top,
                extra_left=0.0,
            )

            # Use default highlight color if not specified
            hl_color = highlight_color or _EVENT_HIGHLIGHT_COLOR

            C = colors or [self.colors[i % len(self.colors)] for i in range(len(tids))]
            L = exonic_len if self.length_mode == "exonic" else genomic_span
            Lmax = float(max(L)) or 1.0

            for i, (y, tid, exs, st, co) in enumerate(
                zip(ycs, tids, exons_list, strands, C)
            ):
                length_bar = None
                if self.show_length:
                    frac = L[i] / Lmax
                    kb = L[i] / 1e3
                    length_bar = {
                        "x0": 0.02,
                        "x1": 0.20,
                        "frac": frac,
                        "label": f"{kb:.1f} kb",
                    }

                # Compute events vs reference (only for non-reference transcripts)
                highlight_intervals = []
                event_types = []
                event_label = None
                
                is_reference = (tid == ref_tid)
                
                if not is_reference and ref_tid and highlight_style:
                    intervals, event_types = _get_events_vs_reference(
                        self.transcript_data, tid, ref_tid
                    )
                    highlight_intervals = intervals
                    
                    if show_event_labels and event_types:
                        event_label = "/".join(event_types)

                self._draw_one(
                    exs,
                    st,
                    co,
                    tid,
                    mapper,
                    y_center=y,
                    cds_bounds=cds_map[tid],
                    show_row_bounds=show_row_bounds,
                    length_bar=length_bar,
                    genome_bounds=(g0, g1),
                    highlight_intervals=highlight_intervals if highlight_style else None,
                    highlight_color=hl_color if highlight_intervals else None,
                    highlight_style=highlight_style,
                    event_label=event_label,
                    event_label_fontsize=event_label_fontsize,
                    spliced_length=int(exonic_len[i]) if (show_spliced_length and not highlight_style) else None,
                )

            contig = self._contig_from_transcripts(tids)
            gene_label = title_gene or self._gene_label_from_transcripts(tids)

            if show_ticks and tids:
                # slightly above the top exon, but within ylim
                ytick = ycs[0] + 1.2 * self.exon_height
                self._draw_top_ruler(
                    ax,
                    mapper,
                    g0,
                    g1,
                    yref=ytick,
                    contig=contig,
                    gene_label=gene_label,
                )

                if show_end_labels and strands:
                    st = strands[0]
                    x_five  = mapper(int(g0)) if st >= 0 else mapper(int(g1))
                    x_three = mapper(int(g1)) if st >= 0 else mapper(int(g0))
                    ha_five  = "left"  if st >= 0 else "right"
                    ha_three = "right" if st >= 0 else "left"
                    kw = dict(va="top", fontsize=14, color=_UI_LIGHT_GREY,
                              fontweight="bold", zorder=2)
                    ax.text(x_five,  ytick - 0.04, "5'", ha=ha_five,  **kw)
                    ax.text(x_three, ytick - 0.04, "3'", ha=ha_three, **kw)

            return fig


