import matplotlib.pyplot as plt
import pandas as pd

def _tp__resolve_counts_df(counts_bed_or_df):
    """Accept a path to regtools BED(6/12) or a preloaded counts DataFrame."""
    if counts_bed_or_df is None:
        return None
    if isinstance(counts_bed_or_df, str):
        return read_regtools_bed12(counts_bed_or_df)
    # assume already a DataFrame with chrom,start0,end0,strand,count
    return counts_bed_or_df

def _tp__sentinels_from_unique_df(u_df):
    """Choose one sentinel per transcript from a unique-junctions DF that has supporting_transcripts* lists."""
    rows = []
    # prefer expressed-support list if present, else the generic list
    support_col = "supporting_transcripts_expressed" if "supporting_transcripts_expressed" in u_df.columns else "supporting_transcripts"
    for _, r in u_df.iterrows():
        ts = r[support_col]
        if not isinstance(ts, (list, tuple)) or len(ts) == 0:
            continue
        width = int(r["intron_end_1b"] - r["intron_start_1b"])
        for tid in ts:
            rows.append({
                "transcript_id": tid,
                "chrom": r["chrom"],
                "intron_start_1b": int(r["intron_start_1b"]),
                "intron_end_1b":   int(r["intron_end_1b"]),
                "strand": r["strand"],
                "junction_id": r["junction_id"],
                "count": int(r["count"]) if "count" in r and pd.notna(r["count"]) else None,
                "width": width
            })
    if not rows:
        return pd.DataFrame(columns=["transcript_id","chrom","intron_start_1b","intron_end_1b","strand","junction_id","count"])
    df = (pd.DataFrame(rows)
            .sort_values(["transcript_id","width"], ascending=[True, False])
            .drop_duplicates(subset=["transcript_id"])
            .drop(columns=["width"])
            .reset_index(drop=True))
    return df

def _tp__build_highlights_from_unique(u_df, *, color_map, label_style="tid", strict=True, alpha=0.30, height=0.10):
    """
    Turn unique junction rows into highlight dicts for the overlay.
    Each highlight draws on any row whose intron matches exactly (strict=True).
    """
    H = []
    # pick expressed-support if present (still length=1 per unique EEJ), else generic list
    support_col = "supporting_transcripts_expressed" if "supporting_transcripts_expressed" in u_df.columns else "supporting_transcripts"
    for _, r in u_df.iterrows():
        # identify the single owning transcript (fully-unique per gene → exactly one)
        owner = None
        ts = r.get(support_col, [])
        if isinstance(ts, (list, tuple)) and len(ts) >= 1:
            owner = ts[0]
        # choose label
        lbl = None
        if label_style == "tid" and owner:
            lbl = owner
        elif label_style == "junction":
            lbl = r["junction_id"]
        elif label_style == "count" and "count" in r and pd.notna(r["count"]):
            lbl = f"{int(r['count'])}"
        elif label_style in ("tid+count","count+tid"):
            parts = []
            if owner: parts.append(owner)
            if "count" in r and pd.notna(r["count"]): parts.append(str(int(r["count"])))
            lbl = " | ".join(parts) if parts else None
        # color per owner if possible, else fallback
        col = color_map.get(owner, color_map.get("__default__", "#e31a1c"))
        H.append({
            "coords": (int(r["intron_start_1b"]), int(r["intron_end_1b"])),
            "color": col,
            "edgecolor": "#222222",
            "alpha": float(alpha),
            "height": float(height),
            "strict": bool(strict),
            "label": lbl
        })
    return H

def _tp__ensure_overlay(tp_self):
    """Return a callable overlay(exons_list,strands,mapper,ycs,highlights) using native helper if present, else a tiny fallback."""
    if hasattr(tp_self, "_overlay_junction_bands"):
        return lambda exons_list, strands, mapper, ycs, highlights: tp_self._overlay_junction_bands(plt.gca(), exons_list, strands, mapper, ycs, highlights)
    # fallback overlay — bezier arc style (sashimi-plot look)
    from matplotlib.path import Path
    from matplotlib.patches import PathPatch
    def _fallback(exons_list, strands, mapper, ycs, highlights):
        ax = plt.gca()
        for exs, st, y in zip(exons_list, strands, ycs):
            ex = [[min(a, b), max(a, b)] for a, b in exs]
            if len(ex) <= 1: continue
            introns = {(ex[k][1]+1, ex[k+1][0]-1) for k in range(len(ex)-1)}
            mapped_spans = [mapper(e) - mapper(s) for s, e in introns]
            max_span = max(mapped_spans) if mapped_spans else 1.0
            # cap arc height to ~70% of inter-row spacing so arcs never cross the ruler
            row_spacings = [abs(ycs[i] - ycs[i+1]) for i in range(len(ycs)-1)]
            max_arc_h = min(row_spacings) * 0.70 if row_spacings else 0.6

            # Pre-pass: for each label, find the widest arc span (label only on widest)
            label_best_span = {}
            for h in highlights:
                s, e = sorted(map(int, h["coords"]))
                if h.get("strict", True) and (s, e) not in introns: continue
                lbl = h.get("label")
                if lbl:
                    span = mapper(e) - mapper(s)
                    if lbl not in label_best_span or span > label_best_span[lbl]:
                        label_best_span[lbl] = span

            for h in highlights:
                s, e = sorted(map(int, h["coords"]))
                if h.get("strict", True) and (s, e) not in introns:
                    continue
                xs, xe = mapper(s), mapper(e)
                col    = h.get("color", "#e31a1c")
                alpha  = float(h.get("alpha", 0.30))
                height = float(h.get("height", 0.10))
                span  = xe - xs
                arc_h = height * 2.5 * (0.35 + 0.65 * span / max(max_span, 1e-9))
                arc_h = max(arc_h, height * 1.3)
                arc_h = min(arc_h, max_arc_h)
                mid   = (xs + xe) / 2.0
                verts = [(xs, y), (xs, y + arc_h), (xe, y + arc_h), (xe, y)]
                codes = [Path.MOVETO, Path.CURVE4, Path.CURVE4, Path.CURVE4]
                arc_alpha = min(1.0, alpha * 2.8)
                patch = PathPatch(Path(verts, codes),
                                  facecolor="none", edgecolor=col,
                                  linewidth=2.2, alpha=arc_alpha,
                                  zorder=4, capstyle="round")
                ax.add_patch(patch)
                dot_r = height * 0.22
                for xp in (xs, xe):
                    circ = plt.Circle((xp, y), dot_r,
                                      color=col, alpha=min(1.0, alpha * 3.5),
                                      zorder=5)
                    ax.add_patch(circ)
                # only label the widest arc for each label value (avoids duplicate overlap)
                lbl = h.get("label")
                if lbl and abs(span - label_best_span.get(lbl, -1)) < 1e-6:
                    ax.text(mid, y + arc_h + height * 0.25, str(lbl),
                            ha="center", va="bottom",
                            fontsize=7, color=col,
                            fontweight="bold",
                            alpha=min(1.0, alpha * 3.5),
                            zorder=6)
    return _fallback

