from .transcript_data import isoform_specific_junctions, isoform_specific_among_expressed, match_counts_to_unique
from typing import Literal
import matplotlib.pyplot as plt
import pandas as pd

def _tp__prep_axes_compat(self, n_rows, *, reserve_panel_space, fig_width=None, extra_top=0.0):
    """
    Call self._prep_axes with whatever signature it supports.
    Works whether _prep_axes has (fig_width, extra_top) or not.
    """
    try:
        # Newer signature
        return self._prep_axes(n_rows, reserve_panel_space=reserve_panel_space,
                               fig_width=fig_width, extra_top=extra_top)
    except TypeError:
        # Older signature: no fig_width/extra_top
        return self._prep_axes(n_rows, reserve_panel_space=reserve_panel_space)

def plot_isoform_specific(
    self,
    gene_key: str,
    transcripts_ids: list[str] | None = None,
    *,
    # which unique junctions
    sentinels: bool = False,
    among_expressed: bool = False,
    counts: str | pd.DataFrame | None = None,
    min_count: int = 1,
    # drawing
    label_style: Literal["tid","count","tid+count","junction","none"] = "none",
    color_by_transcript: bool = True,
    color: str = "#e31a1c",
    alpha: float = 0.30,
    height: float = 0.10,
    # base schematic options
    draw_cds: bool = True,
    show_ticks: bool = True,
    title_gene: str | None = None,
    fig_width: float | None = None,
):
    idx = self.transcript_data._idx

    # rows to draw
    if transcripts_ids is None:
        rows = idx.transcripts_of_gene(gene_key)
        if not rows:
            try:
                idx.tx(gene_key); rows = [gene_key]
            except Exception:
                rows = []
    else:
        rows = list(transcripts_ids)
    if not rows:
        raise ValueError(f"No transcripts to draw for '{gene_key}'.")

    # compute unique junctions (+ optional expression filtering)
    if among_expressed:
        cdf = _tp__resolve_counts_df(counts)
        if cdf is None or cdf.empty:
            raise ValueError("among_expressed=True needs non-empty junction counts.")
        u_df = isoform_specific_among_expressed(idx, gene_key, cdf, min_count=min_count)
        if not u_df.empty and "count" not in u_df.columns:
            # best-effort attach counts on the same coordinates
            u_df = match_counts_to_unique(
                u_df.assign(start0=(u_df["intron_start_1b"].astype(int)-1),
                            end0=u_df["intron_end_1b"].astype(int)),
                cdf, min_count=min_count
            )
    else:
        u_df = isoform_specific_junctions(idx, gene_key)
        if counts is not None:
            cdf = _tp__resolve_counts_df(counts)
            if cdf is not None and not cdf.empty:
                u_df = match_counts_to_unique(u_df, cdf, min_count=min_count)

    if u_df is None or u_df.empty:
        # just draw the schematic (avoid passing fig_width if older signature)
        try:
            return self.draw_transcripts_list(rows, draw_cds=draw_cds,
                                              show_ticks=show_ticks, title_gene=title_gene,
                                              fig_width=fig_width)
        except TypeError:
            return self.draw_transcripts_list(rows, draw_cds=draw_cds,
                                              show_ticks=show_ticks, title_gene=title_gene)

    if sentinels:
        u_df = _tp__sentinels_from_unique_df(u_df)

    # color map
    if color_by_transcript:
        palette = getattr(self, "colors", ["#1f77b4","#ff7f0e","#2ca02c","#d62728","#9467bd"])
        cmap = {t: palette[i % len(palette)] for i, t in enumerate(rows)}
        cmap["__default__"] = color
    else:
        cmap = {"__default__": color}

    H = _tp__build_highlights_from_unique(
        u_df, color_map=cmap,
        label_style=("none" if label_style=="none" else label_style),
        strict=True, alpha=alpha, height=height
    )

    # ----- draw base schematic (compat) -----
    (tids, exons_list, strands, cds_map, mapper, (g0, g1),
     exonic_len, genomic_span) = self._layout_and_mapper(rows, draw_cds=draw_cds)

    fig, ax, ycs = _tp__prep_axes_compat(self, len(tids), reserve_panel_space=False, fig_width=fig_width)

    C = [self.colors[i % len(self.colors)] for i in range(len(tids))]
    L = exonic_len if getattr(self, "length_mode", "exonic") == 'exonic' else genomic_span
    Lmax = float(max(L)) or 1.0
    for i, (y, tid, exs, st, co) in enumerate(zip(ycs, tids, exons_list, strands, C)):
        length_bar = None
        if getattr(self, "show_length", True):
            frac = L[i] / Lmax; kb = L[i] / 1e3
            length_bar = {"x0": 0.02, "x1": 0.20, "frac": frac, "label": f"{kb:.1f} kb"}
        self._draw_one(exs, st, co, tid, mapper, y_center=y,
                       cds_bounds=cds_map[tid], show_row_bounds=False, length_bar=length_bar,
                       spliced_length=int(exonic_len[i]) if getattr(self, 'show_spliced_length', True) else None)

    # overlay
    _overlay = _tp__ensure_overlay(self)
    _overlay(exons_list, strands, mapper, ycs, H)

    contig = self._contig_from_transcripts(tids)
    gene_label = title_gene or self._gene_label_from_transcripts(tids)
    if show_ticks:
        ytick = ycs[0] + self.exon_height
        self._draw_top_ruler(ax, mapper, g0, g1, yref=ytick, contig=contig, gene_label=gene_label)
        if getattr(self, 'show_end_labels', True) and strands:
            st = strands[0]
            x_five  = mapper(int(g0)) if st >= 0 else mapper(int(g1))
            x_three = mapper(int(g1)) if st >= 0 else mapper(int(g0))
            ha_five  = 'left'  if st >= 0 else 'right'
            ha_three = 'right' if st >= 0 else 'left'
            kw = dict(va='top', fontsize=9, color=_UI_LIGHT_GREY, fontweight='bold', zorder=2)
            ax.text(x_five,  ytick - 0.04, "5'", ha=ha_five,  **kw)
            ax.text(x_three, ytick - 0.04, "3'", ha=ha_three, **kw)

    plt.show()

def plot_isoform_sentinels(self, gene_key: str, **kwargs):
    kwargs = dict(kwargs); kwargs["sentinels"] = True
    return self.plot_isoform_specific(gene_key, **kwargs)

# re-patch onto the class
setattr(TranscriptPlots, "plot_isoform_specific", plot_isoform_specific)
setattr(TranscriptPlots, "plot_isoform_sentinels", plot_isoform_sentinels)

