# =====================================================================
# Generic panel layout + heatmap filler (framework)
# =====================================================================


def _panel_width_for(n_cols: int,
                     min_col_w: float = 0.070,
                     max_panel_w: float = 0.92) -> float:
    """
    Heuristic: make panel wider if you have lots of columns, but cap at max_panel_w.
    min_col_w is the 'ideal' width per column.
    """
    if n_cols <= 0:
        return 0.30
    need = n_cols * (min_col_w + 0.026) - (0.026 if n_cols > 0 else 0.0)
    return float(min(max_panel_w, max(0.22, need)))


from dataclasses import dataclass

@dataclass
class LegendConfig:
    # where to put the PSI colourbar
    # 'panel'  : only next to the heatmap/dot panel (current behaviour)
    # 'legend' : only in the legend column on the right
    # 'both'   : panel + legend
    # 'none'   : no PSI colourbar at all
    psi_cbar_location: str = "panel"

    # whether to draw a legend for the categorical band
    # (often redundant when x-axis labels are the same categories)
    show_group_legend: bool = False

    # whether to show the GEX CP10k colourbar in the legend panel
    show_gex_colorbar: bool = True

    # for dot plots: whether to show the dot-size / prevalence legend
    show_prevalence_legend: bool = True



@dataclass
class PanelLayout:
    fig: plt.Figure
    ax_main: plt.Axes
    ax_panel: plt.Axes
    ax_cbar: plt.Axes
    tids: List[str]
    y_centers: List[float]
    mapper: Callable[[int | float], float]
    g0: int
    g1: int
    n_cols: int = 0
    ax_band_top: Optional[plt.Axes] = None
    ax_band_bottom: Optional[plt.Axes] = None
    ax_legend: Optional[plt.Axes] = None   # NEW: legend / extra panel on the far right
    
def make_transcript_panel_layout(
    tp: TranscriptPlots,
    transcripts_ids: List[str],
    *,
    n_panel_cols: int,
    fig_width: float | None = None,
    draw_cds: bool = True,
    show_ruler: bool = True,
    bands_frac_top: float = 0.0,      # fraction above panel
    bands_frac_bottom: float = 0.0,   # fraction below panel
    fig_height: float | None = None,  # force specific canvas height (inches)
    panel_width: float | None = None,  # override computed panel width for cross-plot alignment
) -> PanelLayout:
    """
    Generic builder: draws transcripts on the left and reserves a right-hand
    panel + colorbar axis + far-right legend axis.

    bands_frac_top / bands_frac_bottom are fractions of the panel height
    used for strips above and below the panel, respectively.
    """
    (
        tids,
        exons_list,
        strands,
        cds_map,
        mapper,
        (g0, g1),
        exonic_len,
        genomic_span,
    ) = tp._layout_and_mapper(transcripts_ids, draw_cds=draw_cds)

    # --- choose panel width based on number of columns ---
    tp.panel_width = float(panel_width) if panel_width is not None else tp._panel_width_for(n_panel_cols)

    fig, ax_main, ycs = tp._prep_axes(
        len(tids),
        reserve_panel_space=True,
        fig_width=fig_width,
        extra_top=0.18,
        fig_height=fig_height,
    )

    # ---------------- left transcript glyphs ----------------
    C = [tp.colors[i % len(tp.colors)] for i in range(len(tids))]
    L = exonic_len if tp.length_mode == "exonic" else genomic_span
    Lmax = float(max(L)) or 1.0
    for i, (y, tid, exs, st, co) in enumerate(zip(ycs, tids, exons_list, strands, C)):
        length_bar = None
        if tp.show_length:
            frac = L[i] / Lmax
            kb = L[i] / 1e3
            length_bar = {
                "x0": 0.02,
                "x1": 0.20,
                "frac": frac,
                "label": f"{kb:.1f} kb",
            }
        tp._draw_one(
            exs,
            st,
            co,
            tid,
            mapper,
            y_center=y,
            cds_bounds=cds_map[tid],
            length_bar=length_bar,
            spliced_length=int(exonic_len[i]) if getattr(tp, 'show_spliced_length', True) else None,
        )

    contig = tp._contig_from_transcripts(tids)
    gene_label = tp._gene_label_from_transcripts(tids)
    if show_ruler and tids:
        ytick = ycs[0] + tp.exon_height
        tp._draw_top_ruler(
            ax_main, mapper, g0, g1, yref=ytick, contig=contig, gene_label=gene_label
        )
        if getattr(tp, 'show_end_labels', True) and strands:
            st = strands[0]
            x_five  = mapper(int(g0)) if st >= 0 else mapper(int(g1))
            x_three = mapper(int(g1)) if st >= 0 else mapper(int(g0))
            ha_five  = 'left'  if st >= 0 else 'right'
            ha_three = 'right' if st >= 0 else 'left'
            kw = dict(va='top', fontsize=9, color=_UI_LIGHT_GREY, fontweight='bold', zorder=2)
            ax_main.text(x_five,  ytick - 0.04, "5'", ha=ha_five,  **kw)
            ax_main.text(x_three, ytick - 0.04, "3'", ha=ha_three, **kw)

    # ---------------------------------------------------------
    # Panel geometry + extra space above/below for bands
    # ---------------------------------------------------------
    x0 = tp.panel_x0
    y_top = tp.top_margin + 0.04
    if len(ycs) > 0:
        y_bottom = ycs[-1] - tp.row_pitch / 2 - 0.10
    else:
        y_bottom = -0.2

    panel_total_h = (y_top - y_bottom) or 1.0

    bands_frac_top = max(0.0, min(float(bands_frac_top), 0.9))
    bands_frac_bottom = max(0.0, min(float(bands_frac_bottom), 0.9))

    bands_h_top = panel_total_h * bands_frac_top
    bands_h_bottom = panel_total_h * bands_frac_bottom

    # extend the main axis up/down, but keep panel aligned with transcripts
    ax_main.set_ylim(y_bottom - bands_h_bottom, y_top + bands_h_top)

    hm_h = panel_total_h
    panel_y_bottom = y_bottom
    panel_y_top = y_top

    # ---------------- main panel + colourbar ----------------
    # colourbar axis (same vertical span as panel)
    cax = inset_axes(
        ax_main,
        width=tp.colorbar_width,
        height=hm_h,
        loc="lower left",
        bbox_to_anchor=(
            x0 + tp.panel_width + tp.panel_pad,
            panel_y_bottom,
            tp.colorbar_width,
            hm_h,
        ),
        bbox_transform=ax_main.transData,
        borderpad=0,
    )

    # main panel axis (heatmap / dot panel)
    ax_panel = tp._panel_axes(
        ax_main,
        n_rows=len(tids),
        n_cols=n_panel_cols,
        x0=x0,
        y_top=panel_y_top,
        y_bottom=panel_y_bottom,
    )

    # ---------------- optional top/bottom band axes ----------------
    ax_band_top = None
    if bands_h_top > 0:
        ax_band_top = inset_axes(
            ax_main,
            width="100%",
            height="100%",
            loc="lower left",
            bbox_to_anchor=(x0, y_top, tp.panel_width, bands_h_top),
            bbox_transform=ax_main.transData,
            borderpad=0,
        )
        ax_band_top.set_xlim(-0.5, n_panel_cols - 0.5)
        ax_band_top.set_ylim(0.0, 1.0)
        for s in ax_band_top.spines.values():
            s.set_visible(False)
        ax_band_top.tick_params(
            left=False, labelleft=False, bottom=False, labelbottom=False
        )

    ax_band_bottom = None
    if bands_h_bottom > 0:
        ax_band_bottom = inset_axes(
            ax_main,
            width="100%",
            height="100%",
            loc="lower left",
            bbox_to_anchor=(x0, y_bottom - bands_h_bottom, tp.panel_width, bands_h_bottom),
            bbox_transform=ax_main.transData,
            borderpad=0,
        )
        ax_band_bottom.set_xlim(-0.5, n_panel_cols - 0.5)
        ax_band_bottom.set_ylim(0.0, 1.0)
        for s in ax_band_bottom.spines.values():
            s.set_visible(False)
        ax_band_bottom.tick_params(
            left=False, labelleft=False, bottom=False, labelbottom=False
        )

    # ---------------------------------------------------------
    # Legend axis in figure coordinates (far right)
    # ---------------------------------------------------------
    # [left, bottom, width, height] in figure fraction coordinates
    ax_legend = fig.add_axes([0.86, 0.15, 0.08, 0.7])
    ax_legend.set_axis_off()

    # make sure everything is within the main axis' x-limits
    right = x0 + tp.panel_width + tp.panel_pad + tp.colorbar_width + 0.06
    ax_main.set_xlim(-0.05, right)

    return PanelLayout(
        fig=fig,
        ax_main=ax_main,
        ax_panel=ax_panel,
        ax_cbar=cax,
        tids=tids,
        y_centers=ycs,
        mapper=mapper,
        g0=g0,
        g1=g1,
        n_cols=n_panel_cols,
        ax_band_top=ax_band_top,
        ax_band_bottom=ax_band_bottom,
        ax_legend=ax_legend,
    )






# =====================================================================
# Heatmap / dot helpers
# =====================================================================
def add_heatmap_to_layout(
    tp: TranscriptPlots,
    layout: PanelLayout,
    values: np.ndarray,
    *,
    cmap: str = "magma",
    vmin: float | None = None,
    vmax: float | None = None,
    colorbar_label: str = "PSI",
    col_labels: Optional[List[str]] = None,
    label_wrap: int = 14,
    label_rot: int = 35,
    show_panel_colorbar: bool = True,   # toggle PSI bar next to panel
):
    """
    Fill an existing transcript+panel layout with a heatmap whose look
    matches isoform_dashboard_by_manip_fixedtitle.

    values: [n_iso x n_groups] matrix (rows must match layout.tids order).

    Returns a metadata dict:
      {"artist", "colorbar", "vmin", "vmax", "cmap"}
    so callers can reuse vmin/vmax/cmap for legends.
    """
    M = np.asarray(values, float)
    if M.ndim != 2:
        raise ValueError("values must be 2D [n_rows x n_cols].")

    n_rows, n_cols = M.shape
    if n_rows != len(layout.tids):
        raise ValueError(
            f"Heatmap rows ({n_rows}) must match number of transcripts ({len(layout.tids)})."
        )

    # ---- colour limits ----
    if vmin is None:
        vmin = float(np.nanmin(M)) if M.size else 0.0
    if vmax is None:
        vmax = float(np.nanmax(M)) if M.size else 1.0
    if not np.isfinite(vmin):
        vmin = 0.0
    if not np.isfinite(vmax) or vmax <= vmin:
        vmax = vmin + 1e-6

    # ---- draw heatmap (optionally attach panel colourbar) ----
    im, cb = tp._draw_heatmap_panel(
        layout.fig,
        layout.ax_panel,
        M,
        vmin=vmin,
        vmax=vmax,
        cmap_name=cmap,
        show_grid=False,   # TRAC/NAS panel had no grid
        cbar_label=colorbar_label,
        cax=layout.ax_cbar if show_panel_colorbar else None,
        make_colorbar=show_panel_colorbar,
    )

    # If we didn't use the side colourbar, hide that axis entirely so
    # no empty "bar" appears next to the heatmap.
    if not show_panel_colorbar and layout.ax_cbar is not None:
        layout.ax_cbar.set_axis_off()

    # ---- x labels (wrap + rotate) ----
    if col_labels is None:
        labels = [f"C{j+1}" for j in range(n_cols)]
    else:
        labels = list(col_labels)
        if len(labels) != n_cols:
            raise ValueError("Number of col_labels must match matrix columns.")

    def _wrap(s):
        return "\n".join(
            textwrap.wrap(
                str(s),
                width=max(4, label_wrap),
                break_long_words=False,
            )
        )

    axP = layout.ax_panel
    axP.set_xticks(np.arange(n_cols))
    axP.set_xticklabels(
        [_wrap(m) for m in labels],
        rotation=label_rot,
        ha="right",
        va="top",
        rotation_mode="anchor",
        fontsize=9,
    )
    axP.set_yticks(np.arange(n_rows))
    axP.set_yticklabels([""] * n_rows)
    axP.tick_params(axis="x", pad=2, labelsize=9)

    # ---- return metadata for legend construction ----
    return {
        "artist": im,
        "colorbar": cb,
        "vmin": vmin,
        "vmax": vmax,
        "cmap": cmap,   # name string; caller can do mpl.cm.get_cmap(...)
    }


def add_dotpanel_to_layout(
    tp: TranscriptPlots,
    layout: PanelLayout,
    dot_color: np.ndarray,
    dot_size: np.ndarray,
    *,
    cmap: str = "magma",
    vmin: float | None = None,
    vmax: float | None = None,
    colorbar_label: str = "PSI",
    col_labels: Optional[List[str]] = None,
    label_wrap: int = 14,
    label_rot: int = 35,
    show_panel_colorbar: bool = True,   # toggle PSI bar next to panel
):
    """
    Fill an existing transcript+panel layout with a dotplot.

    dot_color: isoform × group (same shape as dot_size)
    dot_size:  isoform × group in [0,1] (prevalence, coverage, etc.)

    Returns a metadata dict:
      {"artist", "colorbar", "vmin", "vmax", "cmap"}
    so callers can reuse vmin/vmax/cmap for legends.
    """
    C = np.asarray(dot_color, float)
    S = np.asarray(dot_size, float)

    if C.shape != S.shape:
        raise ValueError("dot_color and dot_size must have the same shape.")

    n_rows, n_cols = C.shape
    if n_rows != len(layout.tids):
        raise ValueError(
            f"dot rows ({n_rows}) must match number of transcripts ({len(layout.tids)})."
        )

    # ---- colour limits ----
    if vmin is None:
        vmin = float(np.nanmin(C)) if C.size else 0.0
    if vmax is None:
        vmax = float(np.nanmax(C)) if C.size else 1.0
    if not np.isfinite(vmin):
        vmin = 0.0
    if not np.isfinite(vmax) or vmax <= vmin:
        vmax = vmin + 1e-6

    # ---- draw dot panel (optionally attach side colourbar) ----
    sc, cb = tp._draw_dot_panel(
        layout.fig,
        layout.ax_panel,
        C,
        S,
        vmin=vmin,
        vmax=vmax,
        cmap_name=cmap,
        cbar_label=colorbar_label,
        cax=layout.ax_cbar if show_panel_colorbar else None,
        make_colorbar=show_panel_colorbar,
    )

    # If we didn't use the side colourbar, hide that axis entirely
    # so no empty bar shows next to the dots.
    if not show_panel_colorbar and layout.ax_cbar is not None:
        layout.ax_cbar.set_axis_off()

    # ---- x labels (same wrapping/rotation style as the heatmap) ----
    if col_labels is None:
        labels = [f"C{j+1}" for j in range(n_cols)]
    else:
        labels = list(col_labels)
        if len(labels) != n_cols:
            raise ValueError("Number of col_labels must match matrix columns.")

    def _wrap(s):
        return "\n".join(
            textwrap.wrap(
                str(s),
                width=max(4, label_wrap),
                break_long_words=False,
            )
        )

    axP = layout.ax_panel
    axP.set_xticks(np.arange(n_cols))
    axP.set_xticklabels(
        [_wrap(m) for m in labels],
        rotation=label_rot,
        ha="right",
        va="top",
        rotation_mode="anchor",
        fontsize=9,
    )
    axP.set_yticks(np.arange(n_rows))
    axP.set_yticklabels([""] * n_rows)
    axP.tick_params(axis="x", pad=2, labelsize=9)

    # ---- return metadata for legend construction ----
    return {
        "artist": sc,
        "colorbar": cb,
        "vmin": vmin,
        "vmax": vmax,
        "cmap": cmap,   # name string
    }





# =====================================================================
# AnnData → isoform×group PSI matrix → panel plot
# =====================================================================

def _dense_X(X) -> np.ndarray:
    return np.asarray(X.toarray() if issparse(X) else X, dtype=float)


def _compute_group_matrix_from_adata(
    adata,
    gene_id: str,
    group_col: str,
    *,
    top_n: int = 2,
    estimator: str = "pseudobulk",
    dirichlet_alpha: float = 0.5,
    epsilon: float = 1e-6,
) -> Tuple[List[str], List[str], np.ndarray]:
    """
    Generic: compute isoform×group PSI-like matrix from AnnData.
    """
    if "geneId" not in adata.var:
        return [], [], np.zeros((0, 0), float)

    mask = adata.var["geneId"].astype(str).values == str(gene_id)
    if not np.any(mask):
        return [], [], np.zeros((0, 0), float)

    iso_ids = adata.var_names[mask]
    X = _dense_X(adata.X)
    groups_all = adata.obs[group_col].astype(str).values
    groups = list(dict.fromkeys(groups_all))  # stable order

    G = X[:, mask]  # cells × isoforms
    lib = G.sum(1) + epsilon

    def _psi_cellwise(arr):
        return np.divide(
            arr,
            lib[:, None],
            out=np.zeros_like(arr, float),
            where=(lib[:, None] > 0),
        )

    V_rows = []
    if estimator in ("cell-mean", "cell-median", "coverage-weighted"):
        PSI = _psi_cellwise(G)
        weights = lib if estimator == "coverage-weighted" else None
        for g in groups:
            m = (groups_all == g)
            if not m.any():
                V_rows.append(np.zeros(G.shape[1], float))
                continue
            A = PSI[m]
            if estimator == "cell-median":
                V_rows.append(np.nanmedian(A, axis=0))
            elif estimator == "coverage-weighted":
                w = weights[m]
                w = w / (w.sum() + 1e-12)
                V_rows.append((A * w[:, None]).sum(0))
            else:
                V_rows.append(np.nanmean(A, axis=0))
    elif estimator in ("pseudobulk", "dirichlet"):
        for g in groups:
            m = (groups_all == g)
            if not m.any():
                V_rows.append(np.zeros(G.shape[1], float))
                continue
            S = G[m].sum(0)
            if estimator == "dirichlet":
                S = S + float(dirichlet_alpha)
            denom = float(S.sum()) + epsilon
            V_rows.append((S / denom).ravel())
    else:
        raise ValueError(f"Unknown estimator: {estimator}")

    V = np.vstack(V_rows).T  # isoforms × groups

    if top_n is not None and top_n < len(iso_ids) and V.size:
        keep_idx = np.argsort(V.mean(1))[::-1][:top_n]
        iso_ids = iso_ids[keep_idx]
        V = V[keep_idx, :]

    return iso_ids.tolist(), groups, V


def add_categorical_band_to_layout(
    layout: PanelLayout,
    groups: List[str],
    *,
    color_map: Dict[str, str],
    slot: int = 0,
    n_slots: int = 1,
    which: str = "top",   # "top" or "bottom"
    ax_panel: Optional[plt.Axes] = None,
):
    """
    Draw a categorical strip using imshow on ax_band_top/ax_band_bottom.
    Uses the same imshow+extent approach as the heatmap so column widths
    are pixel-identical — guaranteed alignment.
    """
    which = (which or "top").lower()
    nc = layout.n_cols
    if nc <= 0:
        return

    axB = layout.ax_band_top if which == "top" else layout.ax_band_bottom
    if axB is None:
        return

    # Build 1-row RGBA image: shape (1, nc, 4)
    rgba = np.zeros((1, nc, 4), dtype=float)
    for j, g in enumerate(groups):
        rgba[0, j] = mpl.colors.to_rgba(color_map.get(g, "#bbbbbb"))

    axB.imshow(
        rgba,
        aspect="auto",
        interpolation="nearest",
        extent=(-0.5, nc - 0.5, 0.0, 1.0),
        zorder=2,
    )
    # thin column separators
    for j in range(1, nc):
        axB.axvline(j - 0.5, color="black", linewidth=0.25, zorder=3)


def add_quant_band_to_layout(
    layout: PanelLayout,
    values: np.ndarray,
    *,
    cmap: str = "viridis",
    slot: int = 0,
    n_slots: int = 1,
    which: str = "top",
    ax_panel: Optional[plt.Axes] = None,  # when set, draw on panel axis for perfect alignment
) -> Tuple[mpl.colors.Normalize, mpl.colors.Colormap]:
    """
    Draw a quantitative strip.
    When ax_panel is provided, patches are drawn directly on the panel axis using
    get_xaxis_transform() which guarantees pixel-perfect x-alignment with the heatmap.
    Returns (norm, cmap_obj).
    """
    which = (which or "top").lower()
    n_cols = layout.n_cols
    if n_cols <= 0:
        return mpl.colors.Normalize(vmin=0, vmax=1), mpl.cm.get_cmap(cmap)

    vals = np.asarray(values, float)
    if vals.size == 0:
        vals = np.zeros(n_cols, float)
    if vals.size != n_cols:
        raise ValueError("values length must match number of columns in layout.")

    vmin = float(np.nanmin(vals)) if np.isfinite(np.nanmin(vals)) else 0.0
    vmax = float(np.nanmax(vals)) if np.isfinite(np.nanmax(vals)) else 1.0
    if vmax <= vmin:
        vmax = vmin + 1e-6

    norm = mpl.colors.Normalize(vmin=vmin, vmax=vmax)
    cmap_obj = mpl.cm.get_cmap(cmap)

    axB = layout.ax_band_top if which == "top" else layout.ax_band_bottom
    if axB is None:
        return norm, cmap_obj

    # Build 1-row RGBA image using imshow — same method as heatmap,
    # guarantees pixel-identical column widths.
    rgba = cmap_obj(norm(vals))          # shape (nc, 4)
    for j, v in enumerate(vals):
        if not np.isfinite(v):
            rgba[j] = (0.9, 0.9, 0.9, 1.0)
    rgba = rgba[np.newaxis, :, :]        # (1, nc, 4)

    axB.imshow(
        rgba,
        aspect="auto",
        interpolation="nearest",
        extent=(-0.5, len(vals) - 0.5, 0.0, 1.0),
        zorder=2,
    )
    for j in range(1, len(vals)):
        axB.axvline(j - 0.5, color="black", linewidth=0.25, zorder=3)
    return norm, cmap_obj
